import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { applyCoupon, CouponError } from "@/features/cart/api/coupon.api"
import { getCart } from "@/features/cart/api/get-cart.api"
import { updateCart } from "@/features/cart/api/update-cart.api"
import { CART_PATH } from "@/features/cart/constants/cart.constants"
import { withTotals } from "@/features/cart/helpers/cart-totals"
import { server } from "@/test/server"

const CART_URL = `${siteConfig.apiUrl}${CART_PATH}`

/** A line as DummyJSON sends it. */
const frock = {
  id: 162,
  title: "Blue Frock",
  price: 29.99,
  quantity: 2,
  total: 59.98,
  discountPercentage: 12.13,
  thumbnail: "https://cdn.dummyjson.com/product-images/tops/blue-frock/thumbnail.webp"
}

/** The same line as the schema reads it. */
const frockLine = { ...frock, selected: true, maxQuantity: 10 }

const coupon = { code: "WELCOME10", percent: 10 }

describe("getCart", () => {
  it("reads the lines, starts without a coupon and works out the totals", async () => {
    server.use(
      http.get(CART_URL, () =>
        HttpResponse.json({
          id: 1,
          products: [{ ...frock, discountedTotal: 52.7 }],
          total: 59.98,
          discountedTotal: 52.7,
          userId: 1,
          totalProducts: 1,
          totalQuantity: 2
        })
      )
    )

    const cart = await getCart()

    expect(cart).toEqual(withTotals({ id: 1, items: [frockLine], coupon: null }))
    expect(cart.totals.total).toBe(59.98)
  })
})

describe("updateCart", () => {
  function capturePut(products: unknown[]) {
    const captured: { body?: unknown } = {}
    server.use(
      http.put(CART_URL, async ({ request }) => {
        captured.body = await request.json()
        // PUT names a line's discounted total `discountedPrice` and rounds the cart's to dollars.
        return HttpResponse.json({ id: 1, products, total: 89.97, discountedTotal: 79 })
      })
    )
    return captured
  }

  it("sends every line and replaces the cart, so earlier changes stay", async () => {
    const line = { ...frock, quantity: 3, total: 89.97, discountedPrice: 79 }
    const captured = capturePut([line])
    const cart = withTotals({
      id: 1,
      items: [{ ...frockLine, quantity: 3, selected: false }],
      coupon
    })

    const updated = await updateCart(cart)

    expect(captured.body).toEqual({ merge: false, products: [{ id: 162, quantity: 3 }] })
    // DummyJSON drops the selection, so the line keeps its own.
    expect(updated).toEqual(
      withTotals({
        id: 1,
        items: [{ ...frockLine, quantity: 3, total: 89.97, selected: false }],
        coupon
      })
    )
  })

  it("drops the coupon of a cart left empty", async () => {
    capturePut([])

    await expect(updateCart(withTotals({ id: 1, items: [], coupon }))).resolves.toEqual(
      withTotals({ id: 1, items: [], coupon: null })
    )
  })
})

describe("applyCoupon", () => {
  const cart = withTotals({ id: 1, items: [frockLine], coupon: null })

  it("matches a dummy code in any letter case and works out the discount", async () => {
    const applied = await applyCoupon(cart, " welcome10 ")

    expect(applied.coupon).toEqual(coupon)
    expect(applied.totals.couponDiscount).toBe(6)
  })

  it("turns an unknown code down with a reason the form can word", async () => {
    await expect(applyCoupon(cart, "NOPE")).rejects.toEqual(new CouponError("invalid"))
  })
})

import { queryOptions } from "@tanstack/react-query"

import { getCart } from "@/features/cart/api/get-cart.api"
import { cartKeys } from "@/features/cart/api/query-keys"

export const cartQueryOptions = queryOptions({
  queryKey: cartKeys.all,
  queryFn: ({ signal }) => getCart(signal),
  // DummyJSON keeps no change, so a new fetch would bring its first cart back and undo the
  // visitor's. With a real API, remove this line, unless the selection stays in the browser
  // (`selection.api.ts`).
  staleTime: Infinity
})

import { DUMMY_COUPONS } from "@/features/cart/constants/cart.constants"
import { withTotals } from "@/features/cart/helpers/cart-totals"
import type { Cart } from "@/features/cart/schemas/cart.schema"

/** Why a code was turned down, for the form to word. Add the reasons your API sends. */
type CouponErrorReason = "invalid"

export class CouponError extends Error {
  constructor(readonly reason: CouponErrorReason) {
    super(`Coupon rejected: ${reason}`)
    this.name = "CouponError"
  }
}

/**
 * No request yet: DummyJSON has no coupons. Replace the body with a request to your API, which
 * checks the code and answers with the cart, the coupon applied.
 */
export async function applyCoupon(cart: Cart, code: string): Promise<Cart> {
  const wanted = code.trim().toUpperCase()
  const coupon = DUMMY_COUPONS.find((candidate) => candidate.code === wanted)
  if (!coupon) throw new CouponError("invalid")
  return withTotals({ ...cart, coupon })
}

/** No request yet: replace the body with a request to your API, which answers with the cart. */
export async function removeCoupon(cart: Cart): Promise<Cart> {
  return withTotals({ ...cart, coupon: null })
}

import { api } from "@/lib/api"

import { CART_PATH } from "@/features/cart/constants/cart.constants"
import { withTotals } from "@/features/cart/helpers/cart-totals"
import { cartResponseSchema } from "@/features/cart/schemas/cart.schema"
import type { Cart } from "@/features/cart/schemas/cart.schema"

export async function getCart(signal?: AbortSignal): Promise<Cart> {
  const cart = await api.get(CART_PATH, { schema: cartResponseSchema, signal })
  // DummyJSON has no coupons and no cart totals. Your API sends both with the cart.
  return withTotals({ ...cart, coupon: null })
}

export const cartKeys = {
  all: ["cart"] as const
}

import { withTotals } from "@/features/cart/helpers/cart-totals"
import type { Cart } from "@/features/cart/schemas/cart.schema"

/**
 * No request yet: DummyJSON keeps no selection. Replace the body with a request to your API, which
 * stores which lines go to checkout and answers with the cart. To keep the selection in this
 * browser instead, leave it as it is and keep `staleTime: Infinity` in `cart.queries.ts`: a new
 * fetch would select every line again.
 */
export async function selectCartItems(
  cart: Cart,
  itemIds: number[],
  selected: boolean
): Promise<Cart> {
  const wanted = new Set(itemIds)
  return withTotals({
    ...cart,
    items: cart.items.map((item) => (wanted.has(item.id) ? { ...item, selected } : item))
  })
}

import { api } from "@/lib/api"

import { CART_PATH } from "@/features/cart/constants/cart.constants"
import { withTotals } from "@/features/cart/helpers/cart-totals"
import { cartResponseSchema } from "@/features/cart/schemas/cart.schema"
import type { Cart } from "@/features/cart/schemas/cart.schema"

/**
 * Sends every line, so a line left out is removed. DummyJSON keeps no change and applies each
 * request to its first cart: with `merge: true` and only the changed line, the answer would bring
 * the earlier changes back.
 */
export async function updateCart(cart: Cart): Promise<Cart> {
  const products = cart.items.map(({ id, quantity }) => ({ id, quantity }))
  const updated = await api.put(
    CART_PATH,
    { merge: false, products },
    { schema: cartResponseSchema }
  )
  // DummyJSON keeps neither coupons nor the selection, so both stay as they were; an empty cart
  // drops the coupon. Your API answers with the cart, its coupon, its selection and its totals.
  const selected = new Map(cart.items.map((item) => [item.id, item.selected]))
  return withTotals({
    ...updated,
    items: updated.items.map((item) => ({ ...item, selected: selected.get(item.id) ?? true })),
    coupon: updated.items.length > 0 ? cart.coupon : null
  })
}

import { screen, waitFor, within } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { delay } from "msw"
import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { Cart } from "@/features/cart/components/Cart"
import { CART_PATH } from "@/features/cart/constants/cart.constants"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

const CART_URL = `${siteConfig.apiUrl}${CART_PATH}`
// `Cart` has links, so it renders inside a route.
const CART_PAGE = { path: "/cart" }

const frock = {
  id: 162,
  title: "Blue Frock",
  price: 29.99,
  quantity: 2,
  total: 59.98,
  discountPercentage: 12.13,
  thumbnail: "https://cdn.dummyjson.com/product-images/tops/blue-frock/thumbnail.webp"
}

const ball = {
  id: 138,
  title: "Baseball Ball",
  price: 8.99,
  quantity: 1,
  total: 8.99,
  discountPercentage: 1.71,
  thumbnail:
    "https://cdn.dummyjson.com/product-images/sports-accessories/baseball-ball/thumbnail.webp"
}

type Line = typeof frock

/** DummyJSON's cart: GET answers with these lines, PUT with the lines it was sent. */
function serveCart(lines: Line[] = [frock, ball]) {
  const puts: { products: { id: number; quantity: number }[] }[] = []
  server.use(
    http.get(CART_URL, () => HttpResponse.json({ id: 1, products: lines })),
    http.put(CART_URL, async ({ request }) => {
      const body = (await request.json()) as (typeof puts)[number]
      puts.push(body)
      const products = body.products.flatMap(({ id, quantity }) => {
        const line = lines.find((candidate) => candidate.id === id)
        return line
          ? [{ ...line, quantity, total: Math.round(line.price * quantity * 100) / 100 }]
          : []
      })
      return HttpResponse.json({ id: 1, products })
    })
  )
  return puts
}

async function renderCart() {
  renderWithProviders(<Cart />, { route: CART_PAGE })
  return screen.findByRole("list", { name: "Cart items" })
}

const summary = () => screen.getByRole("region", { name: "Order summary" })
const total = () => within(summary()).getByText("Total").nextElementSibling

describe("Cart", () => {
  it("lists the lines and adds them up", async () => {
    serveCart()
    const list = await renderCart()

    expect(within(list).getAllByRole("listitem")).toHaveLength(2)
    expect(within(list).getByRole("link", { name: "Blue Frock" })).toHaveAttribute(
      "href",
      "/products/162"
    )
    expect(within(summary()).getByText("Subtotal (3 items)")).toBeInTheDocument()
    expect(within(summary()).getByText("-$8.44")).toBeInTheDocument()
    expect(total()).toHaveTextContent("$68.97")
  })

  it("adds up only the selected lines and sends no request for a checkbox", async () => {
    const puts = serveCart()
    const user = userEvent.setup()
    await renderCart()

    await user.click(screen.getByRole("checkbox", { name: "Select Baseball Ball" }))

    await waitFor(() => expect(total()).toHaveTextContent("$59.98"))
    expect(within(summary()).getByText("Subtotal (2 items)")).toBeInTheDocument()
    expect(screen.getByRole("checkbox", { name: "Select all" })).not.toBeChecked()
    expect(puts).toHaveLength(0)
  })

  it("keeps the selection when a quantity changes", async () => {
    serveCart()
    const user = userEvent.setup()
    await renderCart()

    await user.click(screen.getByRole("checkbox", { name: "Select Baseball Ball" }))
    await waitFor(() => expect(total()).toHaveTextContent("$59.98"))
    const frockQuantity = screen.getByRole("group", { name: "Quantity of Blue Frock" })
    await user.click(within(frockQuantity).getByRole("button", { name: "Increase quantity" }))

    await waitFor(() => expect(total()).toHaveTextContent("$89.97"))
    expect(screen.getByRole("checkbox", { name: "Select Baseball Ball" })).not.toBeChecked()
  })

  it("holds checkout until a line is selected", async () => {
    serveCart()
    const user = userEvent.setup()
    await renderCart()

    await user.click(screen.getByRole("checkbox", { name: "Select all" }))

    await waitFor(() => expect(total()).toHaveTextContent("$0.00"))
    expect(within(summary()).getByRole("button", { name: "Proceed to checkout" })).toHaveAttribute(
      "aria-disabled",
      "true"
    )
    expect(
      within(summary()).getByText("Select the products you want to check out.")
    ).toBeInTheDocument()

    await user.click(screen.getByRole("checkbox", { name: "Select all" }))

    await waitFor(() => expect(total()).toHaveTextContent("$68.97"))
    expect(
      within(summary()).getByRole("button", { name: "Proceed to checkout" })
    ).not.toHaveAttribute("aria-disabled", "true")
  })

  it("sends the whole cart when a quantity changes", async () => {
    const puts = serveCart()
    const user = userEvent.setup()
    await renderCart()

    const frockQuantity = screen.getByRole("group", { name: "Quantity of Blue Frock" })
    await user.click(within(frockQuantity).getByRole("button", { name: "Increase quantity" }))

    await waitFor(() => expect(total()).toHaveTextContent("$98.96"))
    expect(puts).toEqual([
      {
        merge: false,
        products: [
          { id: 162, quantity: 3 },
          { id: 138, quantity: 1 }
        ]
      }
    ])
  })

  it("changes the quantity from the list on a narrow cart", async () => {
    const puts = serveCart()
    const user = userEvent.setup()
    await renderCart()

    await user.selectOptions(screen.getByRole("combobox", { name: "Quantity of Blue Frock" }), "5")

    await waitFor(() => expect(total()).toHaveTextContent("$158.94"))
    expect(puts.at(-1)?.products).toEqual([
      { id: 162, quantity: 5 },
      { id: 138, quantity: 1 }
    ])
  })

  it("holds the controls until the cart answers", async () => {
    const puts = serveCart()
    server.use(
      http.put(CART_URL, async ({ request }) => {
        puts.push((await request.json()) as (typeof puts)[number])
        await delay("infinite")
      })
    )
    const user = userEvent.setup()
    await renderCart()

    const increase = within(
      screen.getByRole("group", { name: "Quantity of Blue Frock" })
    ).getByRole("button", { name: "Increase quantity" })
    await user.click(increase)
    await waitFor(() => expect(increase).toHaveAttribute("aria-disabled", "true"))
    await user.click(increase)

    expect(puts).toHaveLength(1)
    expect(increase).toHaveFocus()
  })

  it("turns decrease into remove at one, and keeps the focus on it", async () => {
    serveCart()
    const user = userEvent.setup()
    await renderCart()

    const ballQuantity = screen.getByRole("group", { name: "Quantity of Baseball Ball" })
    expect(within(ballQuantity).queryByRole("button", { name: "Decrease quantity" })).toBeNull()
    expect(
      within(ballQuantity).getByRole("button", { name: "Remove Baseball Ball" })
    ).toBeInTheDocument()

    const frockQuantity = screen.getByRole("group", { name: "Quantity of Blue Frock" })
    const decrease = within(frockQuantity).getByRole("button", { name: "Decrease quantity" })
    await user.click(decrease)

    await waitFor(() => expect(decrease).toHaveAccessibleName("Remove Blue Frock"))
    expect(decrease).toHaveFocus()
  })

  it("removes a line and moves the focus to the list", async () => {
    const puts = serveCart()
    const user = userEvent.setup()
    const list = await renderCart()

    const ballQuantity = screen.getByRole("group", { name: "Quantity of Baseball Ball" })
    await user.click(within(ballQuantity).getByRole("button", { name: "Remove Baseball Ball" }))

    await waitFor(() => expect(within(list).getAllByRole("listitem")).toHaveLength(1))
    expect(puts.at(-1)?.products).toEqual([{ id: 162, quantity: 2 }])
    expect(list).toHaveFocus()
  })

  it("holds checkout while a change is on its way", async () => {
    const puts = serveCart()
    server.use(
      http.put(CART_URL, async ({ request }) => {
        puts.push((await request.json()) as (typeof puts)[number])
        await delay("infinite")
      })
    )
    const user = userEvent.setup()
    await renderCart()

    const frockQuantity = screen.getByRole("group", { name: "Quantity of Blue Frock" })
    await user.click(within(frockQuantity).getByRole("button", { name: "Increase quantity" }))

    const checkout = within(summary()).getByRole("button", { name: "Proceed to checkout" })
    await waitFor(() => expect(checkout).toHaveAttribute("aria-disabled", "true"))
  })

  it("moves the focus to the empty state when the last line goes", async () => {
    serveCart([frock])
    const user = userEvent.setup()
    await renderCart()

    await user.click(screen.getByRole("button", { name: "Remove Blue Frock" }))

    expect(await screen.findByRole("button", { name: "Browse products" })).toHaveFocus()
  })

  it("shows the empty state once the last line is gone", async () => {
    serveCart([frock])
    const user = userEvent.setup()
    await renderCart()

    await user.click(screen.getByRole("button", { name: "Remove Blue Frock" }))

    expect(await screen.findByText("Your cart is empty")).toBeInTheDocument()
    expect(screen.getByRole("button", { name: "Browse products" })).toBeInTheDocument()
    expect(screen.queryByRole("link", { name: "Browse products" })).not.toBeInTheDocument()
  })

  it("turns an unknown coupon down and keeps the focus on the field", async () => {
    serveCart()
    const user = userEvent.setup()
    await renderCart()

    const field = screen.getByLabelText("Coupon code")
    await user.click(screen.getByRole("button", { name: "Apply" }))
    expect(await screen.findByText("Enter a coupon code")).toBeInTheDocument()

    await user.type(field, "NOPE{Enter}")

    expect(await screen.findByText("This coupon isn't valid")).toBeInTheDocument()
    expect(field).toHaveFocus()
    expect(field).toHaveAccessibleDescription("This coupon isn't valid")
  })

  it("applies a coupon, then removes it", async () => {
    serveCart()
    const user = userEvent.setup()
    await renderCart()

    await user.type(screen.getByLabelText("Coupon code"), "welcome10{Enter}")

    const remove = await screen.findByRole("button", { name: "Remove coupon WELCOME10" })
    expect(remove).toHaveFocus()
    expect(within(summary()).getByText("Coupon WELCOME10")).toBeInTheDocument()
    expect(total()).toHaveTextContent("$62.07")

    await user.click(remove)

    expect(await screen.findByLabelText("Coupon code")).toHaveFocus()
    expect(total()).toHaveTextContent("$68.97")
  })

  it("keeps the coupon when a quantity changes", async () => {
    serveCart()
    const user = userEvent.setup()
    await renderCart()

    await user.type(screen.getByLabelText("Coupon code"), "WELCOME10{Enter}")
    await screen.findByRole("button", { name: "Remove coupon WELCOME10" })
    const frockQuantity = screen.getByRole("group", { name: "Quantity of Blue Frock" })
    await user.click(within(frockQuantity).getByRole("button", { name: "Increase quantity" }))

    // 98.96 less 10%, rounded to a cent.
    await waitFor(() => expect(total()).toHaveTextContent("$89.06"))
  })

  it("opens the whole summary from the bar at the bottom", async () => {
    serveCart()
    const user = userEvent.setup()
    await renderCart()

    await user.click(screen.getByRole("button", { name: "Show order summary" }))

    const drawer = await screen.findByRole("dialog", { name: "Order summary" })
    expect(within(drawer).getByLabelText("Coupon code")).toBeInTheDocument()
    expect(within(drawer).getByText("Total").nextElementSibling).toHaveTextContent("$68.97")
  })

  it("offers a retry when the cart does not load", async () => {
    server.use(http.get(CART_URL, () => HttpResponse.json({}, { status: 500 })))
    renderWithProviders(<Cart />, { route: CART_PAGE })

    expect(await screen.findByText("Could not load your cart")).toBeInTheDocument()
    expect(screen.getByRole("button", { name: "Retry" })).toBeInTheDocument()
  })
})

"use client"

import { useState } from "react"

import { Button } from "@/components/ui/button"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle
} from "@/components/ui/empty"
import { CartEmpty } from "@/features/cart/components/CartEmpty"
import { CartItemList } from "@/features/cart/components/CartItemList"
import { CartSkeleton } from "@/features/cart/components/CartSkeleton"
import { CartSummary } from "@/features/cart/components/CartSummary"
import { CartSummaryBar } from "@/features/cart/components/CartSummaryBar"
import { useCart } from "@/features/cart/hooks/use-cart"

export function Cart() {
  const cart = useCart()
  const hasItems = (cart.data?.items.length ?? 0) > 0
  // Once the cart had lines, an empty one means the visitor removed the last: the empty state
  // takes the focus that left with it. A cart that loads empty leaves the focus alone.
  const [hadItems, setHadItems] = useState(false)
  if (hasItems && !hadItems) setHadItems(true)

  // A failed refetch keeps the cart on screen; the error state is only for a cart that never came.
  if (cart.data === undefined) {
    if (cart.isPending) return <CartSkeleton />
    return (
      <Empty role="alert" className="border">
        <EmptyHeader>
          <EmptyTitle>Could not load your cart</EmptyTitle>
          <EmptyDescription>Check your connection and try again.</EmptyDescription>
        </EmptyHeader>
        <EmptyContent>
          <Button variant="outline" disabled={cart.isFetching} onClick={() => cart.refetch()}>
            {cart.isFetching ? "Retrying…" : "Retry"}
          </Button>
        </EmptyContent>
      </Empty>
    )
  }

  if (!hasItems) return <CartEmpty autoFocus={hadItems} />

  return (
    // On phones the fixed bar covers the bottom, so the last line keeps room above it.
    <div className="grid gap-6 pb-24 md:grid-cols-[minmax(0,1fr)_18rem] md:items-start md:pb-0 lg:grid-cols-[minmax(0,1fr)_20rem]">
      <CartItemList cart={cart.data} />
      <CartSummary cart={cart.data} />
      <CartSummaryBar cart={cart.data} />
    </div>
  )
}

/** A plain image that fills its box: Vite has no image service to resize it. */
export function CartImage({ src }: { src: string }) {
  return (
    <img
      src={src}
      alt=""
      loading="lazy"
      decoding="async"
      className="absolute inset-0 size-full object-contain p-2"
    />
  )
}

import { Trash2Icon } from "lucide-react"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { CartImage } from "@/features/cart/components/CartImage"
import { CartLink } from "@/features/cart/components/CartLink"
import { QuantitySelect } from "@/features/cart/components/QuantitySelect"
import { QuantityStepper } from "@/features/cart/components/QuantityStepper"
import { formatPrice } from "@/features/cart/helpers/price"
import { getProductHref } from "@/features/cart/helpers/product-href"
import type { CartItem as CartItemData } from "@/features/cart/schemas/cart.schema"

type CartItemProps = {
  item: CartItemData
  isBusy: boolean
  onSelectedChange: (selected: boolean) => void
  onQuantityChange: (quantity: number) => void
  onRemove: () => void
}

/** A line shows what it costs in all, for its quantity; the unit prices are on the product's page. */
export function CartItem({
  item,
  isBusy,
  onSelectedChange,
  onQuantityChange,
  onRemove
}: CartItemProps) {
  const href = getProductHref(item.id)

  return (
    <li className="flex items-center gap-3 py-4 sm:gap-4">
      <Checkbox
        aria-label={`Select ${item.title}`}
        checked={item.selected}
        disabled={isBusy}
        onCheckedChange={onSelectedChange}
      />
      {/* The title links to the same page, so screen readers and Tab meet one link per line. */}
      <CartLink
        href={href}
        tabIndex={-1}
        aria-hidden
        className="relative size-20 shrink-0 overflow-hidden rounded-md bg-muted/50 sm:size-24"
      >
        <CartImage src={item.thumbnail} />
      </CartLink>
      {/*
        As tall as the image: the name lines up with its top and the quantity with its bottom.
        A narrow list puts the remove button beside the name and the price beside a quantity
        list; a wide one has the stepper, with the price centered on the right.
      */}
      <div className="grid min-w-0 flex-1 grid-cols-[minmax(0,1fr)_auto] content-between gap-x-3 gap-y-3 self-stretch @md:grid-cols-[auto_auto_minmax(0,1fr)_auto] @md:items-center">
        <h3 className="col-start-1 row-start-1 line-clamp-2 self-start text-sm font-medium @md:col-span-3">
          <CartLink href={href} className="hover:underline">
            {item.title}
